import xarray as xr
import numpy as np
from xarray.core.indexes import Index
from xarray.core.variables import Variable

class CustomIndex(Index):
    def __init__(self, x, y):
        self.x = x
        self.y = y

    @classmethod
    def from_variables(cls, variables, options=None):
        # Assume variables has 'x' and 'y'
        x = variables['x'].data
        y = variables['y'].data
        return cls(x, y)

    def create_variables(self, variables=None):
        # Return the original variables plus a new one 'z'
        res = {}
        if variables:
            res.update(variables)

        # Create a new variable 'z' = x + y
        # In a real scenario, we'd use the data from the index
        # For this repro, we just create a dummy variable
        z_data = np.array([1, 2, 3]) # Simplified
        res['z'] = Variable(('x',), z_data, attrs={'name': 'z'})
        return res

def test_custom_index_create_new_variable():
    # Create a dataset with x and y coordinates
    # We need them to be 1D for simplicity, but let's make them match the index
    # Actually, let's just use a simple case.
    ds = xr.Dataset(
        coords={
            "x": [1, 2, 3],
            "y": [4, 5, 6],
        }
    )

    # Set xindex using our CustomIndex
    # We use ['x', 'y'] as coord_names
    ds_indexed = ds.set_xindex(["x", "y"], CustomIndex)

    print(f"Variables in ds_indexed: {list(ds_indexed.variables)}")

    if "z" in ds_indexed.variables:
        print("Success: 'z' variable was created!")
    else:
        print("Failure: 'z' variable was NOT created.")
        exit(1)

if __name__ == "__main__":
    test_custom_index_create_new_variable()

